arguments.new:
    difference() {
        union() {
            linear_extrude(hang_width) polygon(profile);
            // Blade tenon below the shoulder: 24 x 34 with 4 mm corner radii,
            // so it clears the post socket's 5 mm rounded corners. It reaches
            // 2 mm up into the neck so the union is volumetric, not face-only.
            translate([0, 0, hang_width/2]) rotate([-90, 0, 0])
                linear_extrude(hang_shoulder_rel + 2)
                    rounded_rect(2*hang_tenon_half_w, hang_width, 4);
        }
        // 45 deg chamfers on the two crown side edges, limited to the central
        // contact zone |x| <= 36: the box spans start at x = +-36, meet at the
        // edge point (|x|, crown) = (36, hang_top_z(36)) and stop 3 mm inside
        // the crown (tangency point), so the chamfer widens the crown flat to
        // 3 mm at |x| = 36+ and the plate keeps full width beyond it.
        // far side: keeps Z + Y <= hang_top_z(36) + hang_width
        translate([0, hang_top_z(36) + hang_width, hang_width]) rotate([135, 0, 0])
            translate([-36, 0, 0]) cube([72, 40, 40]);
        // bed side: keeps Z - Y >= -hang_top_z(36)
        translate([0, hang_top_z(36), 0]) rotate([-135, 0, 0])
            translate([-36, 0, 0]) cube([72, 40, 40]);
    }
}
